diff --git a/src/jobs/generation.ts b/src/jobs/generation.ts
--- a/src/jobs/generation.ts
+++ b/src/jobs/generation.ts
@@ -21,6 +21,9 @@ export interface ReviewJobIdentity {
   repo: string;
   prNumber: number;
   headSha: string;
+  /** Integration that authorized this review. */
+  forgeIntegrationId?: string;
 }
@@ -77,7 +80,7 @@ export function generationId(identity: ReviewJobIdentity): string {
